import type { RoleDefinition, WorkflowRun, WorkflowStep, WorkflowTemplate } from '../shared/types';
import { buildStepPrompt } from './roles';

export interface WorkflowSeed {
  id: string;
  goal: string;
  cwd: string;
  roles: RoleDefinition[];
  templateId?: string;
  name?: string;
  /** One session id per role, generated by the caller. */
  sessionIds: string[];
  now: number;
}

export function workflowName(goal: string, template: WorkflowTemplate | undefined): string {
  const trimmed = goal.trim().replace(/\s+/g, ' ');
  const short = trimmed.length > 60 ? trimmed.slice(0, 57).trimEnd() + '…' : trimmed;
  return template ? `${template.name}: ${short}` : short;
}

export function createWorkflow(seed: WorkflowSeed): WorkflowRun {
  if (!seed.roles.length) throw new Error('A workflow needs at least one role');
  if (seed.sessionIds.length !== seed.roles.length) throw new Error('One session id per role is required');
  const steps: WorkflowStep[] = seed.roles.map((role, index) => ({
    id: `${seed.id}:${index}`,
    roleId: role.id,
    prompt: index === 0 ? buildStepPrompt(seed.goal, undefined, { index, total: seed.roles.length }) : '',
    status: 'pending',
    sessionId: seed.sessionIds[index] as string,
  }));
  return {
    id: seed.id,
    name: seed.name?.trim() || workflowName(seed.goal, undefined),
    goal: seed.goal.trim(),
    cwd: seed.cwd,
    ...(seed.templateId ? { templateId: seed.templateId } : {}),
    status: 'running',
    steps,
    createdAt: seed.now,
    updatedAt: seed.now,
  };
}

export type WorkflowEvent =
  | { type: 'step-started'; stepIndex: number; at: number }
  | { type: 'step-progress'; stepIndex: number; liveText?: string; currentAction?: string }
  | { type: 'step-finished'; stepIndex: number; at: number; output: string; costUsd?: number; turns?: number }
  | { type: 'step-errored'; stepIndex: number; at: number; error: string }
  | { type: 'cancelled'; at: number };

/** Pure transition. Returns a new workflow; never mutates the input. */
export function applyEvent(workflow: WorkflowRun, event: WorkflowEvent, roles: RoleDefinition[]): WorkflowRun {
  const steps = workflow.steps.map((s) => ({ ...s }));
  const at = 'at' in event ? event.at : workflow.updatedAt;
  const step = 'stepIndex' in event ? steps[event.stepIndex] : undefined;
  if ('stepIndex' in event && !step) return workflow;
  let status = workflow.status;
  let error = workflow.error;

  switch (event.type) {
    case 'step-started':
      Object.assign(step as WorkflowStep, { status: 'running', startedAt: event.at, liveText: undefined, currentAction: undefined, error: undefined });
      break;
    case 'step-progress':
      if ((step as WorkflowStep).status !== 'running') return workflow;
      if (event.liveText !== undefined) (step as WorkflowStep).liveText = event.liveText;
      if (event.currentAction !== undefined) (step as WorkflowStep).currentAction = event.currentAction;
      break;
    case 'step-finished': {
      const s = step as WorkflowStep;
      Object.assign(s, { status: 'finished', endedAt: event.at, output: event.output, liveText: undefined, currentAction: undefined, costUsd: event.costUsd, turns: event.turns });
      const nextIndex = event.stepIndex + 1;
      const next = steps[nextIndex];
      if (next) {
        const role = roles.find((r) => r.id === s.roleId);
        next.prompt = buildStepPrompt(workflow.goal, { roleName: role?.name ?? s.roleId, output: event.output }, { index: nextIndex, total: steps.length });
      } else {
        status = 'finished';
      }
      break;
    }
    case 'step-errored':
      Object.assign(step as WorkflowStep, { status: 'errored', endedAt: event.at, error: event.error, liveText: undefined, currentAction: undefined });
      for (const s of steps) if (s.status === 'pending') s.status = 'cancelled';
      status = 'errored';
      error = event.error;
      break;
    case 'cancelled':
      for (const s of steps) {
        if (s.status === 'running') Object.assign(s, { status: 'cancelled', endedAt: event.at, liveText: undefined, currentAction: undefined });
        else if (s.status === 'pending') s.status = 'cancelled';
      }
      status = 'cancelled';
      break;
  }
  return { ...workflow, steps, status, ...(error !== undefined ? { error } : {}), updatedAt: at };
}

/** Index of the next step to run, or undefined when nothing is left. */
export function nextPendingStep(workflow: WorkflowRun): number | undefined {
  if (workflow.status !== 'running') return undefined;
  if (workflow.steps.some((s) => s.status === 'running')) return undefined;
  const index = workflow.steps.findIndex((s) => s.status === 'pending');
  return index === -1 ? undefined : index;
}

/** A workflow persisted while a step was running cannot be resumed: mark it interrupted. */
export function markInterrupted(workflow: WorkflowRun, at: number): WorkflowRun {
  if (workflow.status !== 'running') return workflow;
  const running = workflow.steps.findIndex((s) => s.status === 'running');
  const stepIndex = running !== -1 ? running : Math.max(0, workflow.steps.findIndex((s) => s.status === 'pending'));
  return applyEvent(workflow, { type: 'step-errored', stepIndex, at, error: 'AgentLens was closed while this step was running' }, []);
}

/* ---------- Claude Code stream-json parsing ---------- */

export type StreamSignal =
  | { kind: 'init'; sessionId: string; model?: string }
  | { kind: 'assistant-text'; text: string }
  | { kind: 'tool-call'; name: string; summary: string }
  | { kind: 'result'; isError: boolean; text: string; costUsd?: number; turns?: number }
  | { kind: 'other' };

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function toolSummary(name: string, input: unknown): string {
  if (!isRecord(input)) return name;
  const path = [input.file_path, input.path, input.notebook_path].find((v) => typeof v === 'string') as string | undefined;
  if (path) return `${name} ${path}`;
  if (typeof input.command === 'string') return `${name}: ${input.command.slice(0, 80)}`;
  if (typeof input.pattern === 'string') return `${name} ${input.pattern}`;
  if (typeof input.description === 'string') return `${name}: ${input.description}`;
  return name;
}

/** Interpret one line of `claude -p --output-format stream-json` output. */
export function parseStreamLine(line: string): StreamSignal[] {
  const trimmed = line.trim();
  if (!trimmed.startsWith('{')) return [];
  let record: unknown;
  try {
    record = JSON.parse(trimmed);
  } catch {
    return [];
  }
  if (!isRecord(record)) return [];
  if (record.type === 'system' && record.subtype === 'init') {
    return [{ kind: 'init', sessionId: String(record.session_id ?? ''), ...(typeof record.model === 'string' ? { model: record.model } : {}) }];
  }
  if (record.type === 'assistant' && isRecord(record.message) && Array.isArray(record.message.content)) {
    const signals: StreamSignal[] = [];
    const texts: string[] = [];
    for (const block of record.message.content) {
      if (!isRecord(block)) continue;
      if (block.type === 'text' && typeof block.text === 'string' && block.text.trim()) texts.push(block.text);
      if (block.type === 'tool_use' && typeof block.name === 'string') signals.push({ kind: 'tool-call', name: block.name, summary: toolSummary(block.name, block.input) });
    }
    if (texts.length) signals.unshift({ kind: 'assistant-text', text: texts.join('\n') });
    return signals.length ? signals : [{ kind: 'other' }];
  }
  if (record.type === 'result') {
    const isError = record.is_error === true || (typeof record.subtype === 'string' && record.subtype !== 'success');
    const text = typeof record.result === 'string' ? record.result : isError ? String(record.subtype ?? 'error') : '';
    return [
      {
        kind: 'result',
        isError,
        text,
        ...(typeof record.total_cost_usd === 'number' ? { costUsd: record.total_cost_usd } : {}),
        ...(typeof record.num_turns === 'number' ? { turns: record.num_turns } : {}),
      },
    ];
  }
  return [{ kind: 'other' }];
}
